import {validateJournal} from './journal.mjs';
export const VERSION=1;
export const WORKOUTS={upper:{name:'上肢',days:'周一 · 周四',hint:'胸、背、肩 · 余力约 2 次',ids:['push','row','press']},lower:{name:'下肢＋腹部',days:'周二',hint:'动作完整、过程可控',ids:['lunge','hinge','curl','plank']},light:{name:'轻下肢＋核心',days:'周五',hint:'为羽毛球留余力 · 腿部留 3–4 次',ids:['squat','bridge','side']}};
const spec=[['push','标准俯卧撑',3,6,10,90,'不塌腰；从每组 6–8 次试起。'],['row','坐姿脚踩弹力带划船',3,8,15,90,'固定握距与幅度，不后仰甩动。'],['press','脚踩弹力带推举',2,8,12,60,'保持控制，不后仰腰部。'],['lunge','反向弓步',2,8,12,90,'左右完成算一组；数值填写每侧次数。'],['hinge','弹力带罗马尼亚硬拉',3,10,15,90,'臀向后、背稳定，不过度下探。'],['curl','反向卷腹',2,8,12,60,'缓慢卷起骨盆，不甩腿；难控制时改死虫。'],['plank','前臂平板',2,20,40,60,'正常呼吸，在塌腰前结束。'],['squat','自重深蹲',2,10,15,60,'保留 3–4 次规范动作的余力。'],['bridge','臀桥',2,12,20,60,'不顶腰，保留 3–4 次余力。'],['side','侧平板',2,15,30,60,'左右分别完成 2 组；数值填写每侧秒数。']];
export function fresh(){return {schema:VERSION,created:new Date().toISOString(),exercises:Object.fromEntries(spec.map(([id,name,sets,min,max,rest,cue])=>[id,{id,name,sets,min,max,rest,cue,unit:['plank','side'].includes(id)?'秒':'次',sides:['lunge','side'].includes(id),light:['squat','bridge'].includes(id),target:Array(sets).fill(min),load:['row','press','hinge'].includes(id)?'现有 40 磅带 · 固定握距':'当前动作版本',next:null,blocked:false,records:[],changes:[],validation:null}])),temporary:{},events:[]};}
export function localDate(d=new Date()){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
export const clone=x=>JSON.parse(JSON.stringify(x));
export function startValidation(s,id){const e=s.exercises[id];if(e.blocked)throw Error('该动作已暂停；请先确认恢复。');e.validation={streak:0,lastDate:null};e.updated=new Date().toISOString();return '验证已开始：只记录接下来两次该动作的实际训练。';}
function base(e){return {target:[...e.target],load:e.load,next:clone(e.next)};}
export function record(s,id,input){const e=s.exercises[id];if(!e)throw Error('找不到动作');if(!/^\d{4}-\d{2}-\d{2}$/.test(input.date)||Number.isNaN(Date.parse(input.date+'T12:00:00'))||new Date(input.date+'T12:00:00').toISOString().slice(0,10)!==input.date||input.date>localDate())throw Error('请填写有效日期，不能晚于今天。');if(e.records.some(r=>r.date===input.date))throw Error('这个动作当天已有记录，不能重复提交或重复计算进阶。');const sets=input.temporary?Math.max(1,e.sets-1):e.sets;if(!Array.isArray(input.values)||input.values.length!==sets||input.values.some(n=>!Number.isInteger(n)||n<0||n>600))throw Error('请填写每组实际完成量（0–600 的整数）。');if(e.records.length&&input.date<e.records.at(-1).date)throw Error('请按训练日期顺序记录；较早的遗漏可写入备注或周报。');if(!['normal','form','fatigue','pain'].includes(input.quality)||!['unknown','0','2','4','steady'].includes(input.rir))throw Error('请选择动作、余力和恢复情况。');if(!['yes','no','unknown'].includes(input.comparable))throw Error('请确认两次训练条件。');
const r={id:crypto.randomUUID(),...clone(input),logged:new Date().toISOString(),load:e.load,target:[...e.target],outcome:'已记录；当前安排保持。'};e.records.push(r);e.updated=r.logged;
if(input.quality==='pain'){e.blocked=true;e.validation=null;r.outcome='该动作已暂停自动推进。停止相关动作；持续或加重的不适需评估。';return r;}
if(e.blocked){r.outcome='记录已保留；动作仍暂停，未运行进阶。';return r;}
if(!e.validation)return r;
const v=e.validation;const sufficient=e.unit==='秒'?input.rir==='steady':(e.light?input.rir==='4':['2','4'].includes(input.rir));const good=!input.temporary&&input.quality==='normal'&&sufficient&&input.comparable==='yes'&&input.values.every((n,i)=>n>=e.target[i]);
if(!good){v.streak=0;v.lastDate=input.date;r.outcome='未满足可比、规范、余力及恢复条件；验证计数归零，计划保持。';return r;}
v.streak++;v.lastDate=input.date;if(v.streak<2){r.outcome='验证 1 / 2 达标；下一次该动作训练再验证。';return r;}
const before=base(e),cap=input.values.every(n=>n>=e.max)&&e.records.at(-2)?.values.every(n=>n>=e.max);
if(cap||e.target.every(n=>n>=e.max)){
if(!e.next){e.validation=null;r.outcome='两次验证达标，已到上限。尚无预设下一档，保持当前安排；可先设置可用阻力。';return r;}
e.load=e.next.label;e.next=null;e.target=Array(e.sets).fill(e.min);
}else{const step=e.unit==='秒'?5:1;e.target=e.target.map(n=>Math.min(e.max,n+step));}
const change={id:crypto.randomUUID(),at:new Date().toISOString(),date:input.date,before,after:base(e),reason:'两次可比训练达到目标，动作规范、余力合适且恢复正常。',undone:false};e.changes.push(change);e.validation=null;r.outcome=`已自动更新：${e.load}，每组目标 ${e.target.join(' / ')} ${e.unit}。可在调整历史撤销。`;s.events.push({type:'progress',exercise:id,change:change.id,at:change.at});return r;
}
export function undo(s,id,changeId){const e=s.exercises[id],c=e.changes.find(x=>x.id===changeId);if(!c||c.undone||e.changes.filter(x=>!x.undone).at(-1)!==c)throw Error('只能撤销该动作最近一次有效调整。');if(e.records.some(r=>r.logged>c.at))throw Error('调整后已有新训练记录；请用当前档位设置修正，保留完整历史。');e.target=[...c.before.target];e.load=c.before.load;e.next=clone(c.before.next);c.undone=true;e.validation=null;e.updated=new Date().toISOString();s.events.push({type:'undo',exercise:id,at:e.updated});}
export function configure(s,id,{load,next}){const e=s.exercises[id];const clean=x=>String(x??'').trim();load=clean(load);next=clean(next);if(!load||load.length>100||next.length>100)throw Error('档位名称必填且不超过 100 字。');if(next&&next===load)throw Error('下一档应与当前档位不同。');const before=base(e);e.load=load;e.next=next?{label:next}:null;e.validation=null;const at=new Date().toISOString();e.updated=at;e.changes.push({id:crypto.randomUUID(),at,date:localDate(),before,after:base(e),reason:'本人设置当前档位与下一档，进阶验证重新计数。',kind:'configure',undone:false});s.events.push({type:'configure',exercise:id,at});}
export function validateBackup(s){if(!s||s.schema!==VERSION||!s.exercises||!Array.isArray(s.events)||!s.temporary||typeof s.temporary!=='object')throw Error('这不是兼容的训练备份。');const defs=fresh().exercises;for(const [id,d]of Object.entries(defs)){const e=s.exercises[id];if(!e||e.id!==id||e.sets!==d.sets||e.min!==d.min||e.max!==d.max||e.unit!==d.unit||!Array.isArray(e.target)||e.target.length!==e.sets||e.target.some(n=>!Number.isInteger(n)||n<e.min||n>e.max)||typeof e.load!=='string'||!Array.isArray(e.records)||!Array.isArray(e.changes)||typeof e.blocked!=='boolean'||(e.next!==null&&(!e.next||typeof e.next.label!=='string'))||(e.validation!==null&&(!e.validation||![0,1].includes(e.validation.streak))))throw Error('备份内容不完整或训练参数不匹配。');for(const r of e.records){if(typeof r.id!=='string'||typeof r.date!=='string'||typeof r.logged!=='string'||typeof r.outcome!=='string'||!Array.isArray(r.values)||r.values.length!==(r.temporary?Math.max(1,e.sets-1):e.sets)||r.values.some(n=>!Number.isInteger(n)||n<0||n>600)||!['normal','form','fatigue','pain'].includes(r.quality)||!['unknown','0','2','4','steady'].includes(r.rir))throw Error('备份含无效记录。');}for(const c of e.changes){if(typeof c.id!=='string'||typeof c.at!=='string'||typeof c.date!=='string'||typeof c.reason!=='string'||typeof c.undone!=='boolean'||![c.before,c.after].every(x=>x&&typeof x.load==='string'&&Array.isArray(x.target)&&x.target.length===e.sets&&x.target.every(n=>Number.isInteger(n)&&n>=e.min&&n<=e.max)&&(x.next===null||typeof x.next?.label==='string')))throw Error('备份含无效调整历史。');}e.name=d.name;e.cue=d.cue;e.rest=d.rest;e.light=d.light;e.sides=d.sides;}const out=clone(s);out.journal=validateJournal(s.journal);return out;}
export function weekRange(date=localDate()){const d=new Date(date+'T12:00:00');d.setDate(d.getDate()-((d.getDay()+6)%7));const from=localDate(d);d.setDate(d.getDate()+6);return [from,localDate(d)];}
export function markdown(s,date=localDate()){const[from,to]=weekRange(date);let out=`---\ntype: training_week\nweek_start: ${from}\nweek_end: ${to}\nexported: ${localDate()}\n---\n\n# 训练周报｜${from} — ${to}\n\n> 仅统计已记录事实；未记录不等于未训练。当前计划为导出时快照。\n\n## 当前训练计划\n\n`;for(const w of Object.values(WORKOUTS)){out+=`### ${w.days}｜${w.name}\n\n| 动作 | 当前目标 | 档位 |\n|---|---|---|\n`;for(const id of w.ids){const e=s.exercises[id];out+=`| ${e.name} | ${e.sides?'每侧 ':''}${e.sets} 组 × ${e.target.join('/')} ${e.unit}${e.blocked?'（暂停）':''} | ${e.load.replaceAll('|','／').replaceAll('\n',' ')} |\n`;}out+='\n';}out+='## 本周实际记录\n\n';let count=0;for(const e of Object.values(s.exercises))for(const r of e.records.filter(r=>r.date>=from&&r.date<=to)){out+=`- ${r.date}｜${e.name}：${e.sides?'每侧 ':''}${r.values.join('/')} ${e.unit}；余力 ${r.rir==='unknown'?'不确定':r.rir==='steady'?'稳定、有余量':r.rir==='4'?'4次左右或更多':r.rir==='2'?'2–3次':'0–1次'}；状态 ${r.quality}；${r.temporary?'本次减量；':''}${r.outcome}\n`;count++;}if(!count)out+='本周尚无已记录训练。\n';out+='\n## 本周计划变更\n\n';let changes=0;for(const e of Object.values(s.exercises))for(const c of e.changes.filter(c=>c.date>=from&&c.date<=to)){out+=`- ${c.date}｜${e.name}：${c.before.load} ${c.before.target.join('/')} → ${c.after.load} ${c.after.target.join('/')}；${c.reason}${c.undone?'（已撤销，原训练记录保留）':''}\n`;changes++;}if(!changes)out+='本周无自动进阶变更。\n';out+='\n## 下周的一个决定\n\n- 保持／递进／减少：\n- 依据：\n\n> 正课最多30分钟，热身另计4–5分钟；羽毛球按实际日期调整。\n';return out;}
